mapper.select:
SELECT s.student_id AS studentId, s.student_no AS studentNo, s.student_name AS studentName, s.gender AS gender, s.phone AS phone, s.email AS email, s.birthday AS birthday, s.class_id AS classId, c.class_name AS className, c.grade AS grade, s.enrollment_year AS enrollmentYear, s.student_status AS studentStatus, s.student_remark AS studentRemark, s.gmt_create AS gmtCreate, s.gmt_modified AS gmtModified FROM edu_student s LEFT JOIN edu_class c ON s.class_id = c.class_id AND c.class_deleted = 0 WHERE s.student_deleted = 0
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND s.student_name LIKE CONCAT('%', #{studentName}, '%')
AND s.class_id = #{classId}
AND s.gender = #{gender}
AND s.student_status = #{studentStatus}
AND c.grade = #{grade}
AND c.class_name LIKE CONCAT('%', #{className}, '%')
ORDER BY s.student_no
